#include <vector>
#include <cstddef>
#include <algorithm>
#include <omp.h>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) return 0;
    // Expect A.size() == N*N; if not, compute over the available prefix safely.
    const size_t total = A.size();
    const size_t NN = N * N;
    const size_t usable = std::min(total, NN);

    int globalMax = 0;

    #pragma omp parallel for reduction(max:globalMax) schedule(static)
    for (size_t i = 0; i < N; ++i) {
        int deg = 0;
        const size_t rowStart = i * N;
        if (rowStart >= usable) {
            // No data for this row
            globalMax = std::max(globalMax, 0);
            continue;
        }
        const size_t rowEnd = std::min(rowStart + N, usable);
        for (size_t j = rowStart; j < rowEnd; ++j) {
            // For undirected graphs, degree is count of neighbors; ignore self-loop on diagonal.
            const size_t col = j - rowStart;
            if (col != i && A[j] != 0) ++deg;
        }
        if (deg > globalMax) globalMax = deg; // safe due to reduction(max)
    }

    return globalMax;
}
